import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Checkbox,
  FormControlLabel,
  Grid,
  Typography,
} from '@mui/material';
import { Button, Dialog } from '../../../../components/ui';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import {
  buildDownloadFilterPayload,
  getDownloadableColumns,
  hasSelectedDownloadColumns,
  setAllDownloadColumns,
  summarizeAppliedDownloadFilters,
  toggleDownloadColumn,
} from '../utils/recordDownloadUtils';

export default function DownloadModal({
  open,
  onClose,
  workspaceId,
  tableId,
  columns = [],
  columnVisibility = {},
  filters = {},
  search = '',
  activeFilterCount = 0,
}) {
  const { showSnackBar } = useSnackBar();
  const [selectedColumns, setSelectedColumns] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const downloadableColumns = useMemo(
    () => getDownloadableColumns(columns),
    [columns]
  );

  useEffect(() => {
    if (!open) return;
    setSelectedColumns(
      downloadableColumns.reduce((selection, column) => {
        selection[column.key] = columnVisibility[column.key] !== false;
        return selection;
      }, {})
    );
  }, [columnVisibility, downloadableColumns, open]);

  const filterSummary = useMemo(
    () => summarizeAppliedDownloadFilters({ filters, search, activeFilterCount }),
    [activeFilterCount, filters, search]
  );

  const allSelected = downloadableColumns.length > 0
    && downloadableColumns.every((column) => selectedColumns[column.key]);
  const someSelected = downloadableColumns.some((column) => selectedColumns[column.key]);

  const handleDownload = async () => {
    if (!hasSelectedDownloadColumns(selectedColumns)) {
      showSnackBar('Select at least one column to download', 'warning');
      return;
    }

    setIsSubmitting(true);
    try {
      const filterPayload = buildDownloadFilterPayload({
        workspaceId,
        tableId,
        filters,
      });
      await recordService.downloadRecords(filterPayload, selectedColumns);
      showSnackBar(RECORD_COPY.success.downloadStarted, 'success');
      onClose?.();
    } catch {
      showSnackBar(RECORD_COPY.errors.downloadFailed, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      title={RECORD_COPY.download.title}
      maxWidth="md"
      showCloseButton={!isSubmitting}
      actions={
        <>
          <Button variant="secondary" onClick={onClose} disabled={isSubmitting}>
            {RECORD_COPY.download.cancel}
          </Button>
          <Button
            variant="primary"
            onClick={handleDownload}
            loading={isSubmitting}
            disabled={!someSelected}
          >
            {RECORD_COPY.download.confirm}
          </Button>
        </>
      }
    >
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
        <Box sx={{ pb: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
          <Typography variant="subtitle2" fontWeight={600} gutterBottom>
            {RECORD_COPY.download.appliedFilters}
          </Typography>
          {filterSummary.hasAny ? (
            <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1 }}>
              {filterSummary.hasDateRange ? (
                <Typography variant="body2" color="text.secondary">
                  <strong>{RECORD_COPY.download.dateRange}:</strong> {filterSummary.dateRangeLabel}
                </Typography>
              ) : null}
              {filterSummary.hasSearch ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: filterSummary.hasDateRange ? 1 : 0 }}>
                  <strong>{RECORD_COPY.download.search}:</strong> {filterSummary.searchLabel}
                </Typography>
              ) : null}
              {filterSummary.hasDynamicFilters ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                  <strong>{RECORD_COPY.download.dynamicFilters(filterSummary.dynamicFilterCount)}</strong>
                </Typography>
              ) : null}
            </Box>
          ) : (
            <Typography variant="body2" color="text.secondary" fontStyle="italic">
              {RECORD_COPY.download.noFilters}
            </Typography>
          )}
        </Box>

        <Box>
          <Typography variant="subtitle2" fontWeight={600} gutterBottom>
            {RECORD_COPY.download.selectColumns}
          </Typography>

          <FormControlLabel
            control={
              <Checkbox
                size="small"
                checked={allSelected}
                indeterminate={someSelected && !allSelected}
                onChange={(event) => {
                  setSelectedColumns(setAllDownloadColumns(selectedColumns, event.target.checked));
                }}
              />
            }
            label={RECORD_COPY.download.selectAll}
            sx={{ width: '100%', mb: 1, borderBottom: '1px solid', borderColor: 'divider' }}
          />

          <Grid container spacing={1}>
            {downloadableColumns.map((column) => (
              <Grid item xs={12} sm={6} md={4} key={column.key}>
                <FormControlLabel
                  control={
                    <Checkbox
                      size="small"
                      checked={Boolean(selectedColumns[column.key])}
                      onChange={(event) => {
                        setSelectedColumns(
                          toggleDownloadColumn(selectedColumns, column.key, event.target.checked)
                        );
                      }}
                    />
                  }
                  label={column.header || column.key}
                />
              </Grid>
            ))}
          </Grid>
        </Box>
      </Box>
    </Dialog>
  );
}
