import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Avatar,
  Box,
  Stack,
  Typography,
} from '@mui/material';
import ChatBubbleOutlineIcon from '@mui/icons-material/ChatBubbleOutline';
import SendIcon from '@mui/icons-material/Send';
import { useRecoilValue } from 'recoil';
import { Button, Dialog, EmptyState, FormTextArea } from '../../../../components/ui';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { userInformationAtom } from '../../../../Services/_states';
import { dateFormate } from '../../../../utils/helper.jsx';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import { getRecordMongoId } from '../utils/recordInlineEditUtils';

function getCommentAuthor(comment = {}) {
  return comment.comment_by || comment.created_by || 'Team member';
}

function getCommentInitial(comment = {}) {
  const author = getCommentAuthor(comment);
  return author?.charAt?.(0)?.toUpperCase() || '?';
}

function normalizeComments(selectedRow) {
  const internal = Array.isArray(selectedRow?.internal_comments)
    ? selectedRow.internal_comments
    : [];

  if (internal.length > 0) {
    return internal;
  }

  const lastComment = selectedRow?.last_machadalo_comment;
  if (lastComment?.comment) {
    return [lastComment];
  }

  return [];
}

function CommentThreadItem({ comment, semantic, typography, chat }) {
  const author = getCommentAuthor(comment);

  return (
    <Box
      sx={{
        display: 'flex',
        gap: 1.5,
        p: 1.75,
        borderRadius: 2,
        bgcolor: semantic.surfaces.surface,
        border: `1px solid ${semantic.borders.border}`,
        boxShadow: '0 1px 2px rgba(15, 23, 42, 0.04)',
      }}
    >
      <Avatar
        sx={{
          width: 38,
          height: 38,
          fontSize: typography.fontSizeSm,
          fontWeight: typography.fontWeightSemibold,
          bgcolor: chat.primarySurface,
          color: chat.primaryDark,
        }}
      >
        {getCommentInitial(comment)}
      </Avatar>

      <Box sx={{ minWidth: 0, flex: 1 }}>
        <Stack
          direction="row"
          alignItems="baseline"
          justifyContent="space-between"
          gap={1}
          sx={{ mb: 0.75 }}
        >
          <Typography
            sx={{
              fontSize: typography.fontSizeSm,
              fontWeight: typography.fontWeightSemibold,
              color: semantic.text.primary,
            }}
          >
            {author}
          </Typography>
          {comment?.created_at ? (
            <Typography
              sx={{
                fontSize: typography.fontSizeXs ?? '0.75rem',
                color: semantic.text.muted,
                whiteSpace: 'nowrap',
              }}
            >
              {dateFormate(comment.created_at, 'DD MMM YYYY, hh:mm A')}
            </Typography>
          ) : null}
        </Stack>

        <Typography
          sx={{
            fontSize: typography.fontSizeMd,
            lineHeight: 1.6,
            color: semantic.text.secondary,
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-word',
          }}
        >
          {comment?.comment || ''}
        </Typography>
      </Box>
    </Box>
  );
}

export default function CommentModal({
  open,
  onClose,
  selectedRow,
  onSuccess,
}) {
  const { showSnackBar } = useSnackBar();
  const { semantic, typography, chat } = useFeatureTheme();
  const loggedInUser = useRecoilValue(userInformationAtom);
  const [comments, setComments] = useState([]);
  const [draft, setDraft] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const recordId = getRecordMongoId(selectedRow);
  const leadId = selectedRow?.lead_id || selectedRow?.id;
  const authorName =
    loggedInUser?.username
    || loggedInUser?.profile?.username
    || loggedInUser?.profile?.first_name
    || 'You';

  useEffect(() => {
    if (!open) {
      setDraft('');
      return;
    }
    setComments(normalizeComments(selectedRow));
  }, [open, selectedRow]);

  const subtitle = useMemo(() => {
    const leadLabel = RECORD_COPY.comments.subtitle(leadId);
    const countLabel = RECORD_COPY.comments.count(comments.length);
    return `${leadLabel} · ${countLabel}`;
  }, [comments.length, leadId]);

  const handleSubmit = useCallback(async () => {
    const trimmed = draft.trim();
    if (!trimmed) {
      showSnackBar('Please enter a comment', 'warning');
      return;
    }
    if (!recordId) {
      showSnackBar(RECORD_COPY.errors.commentFailed, 'error');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await recordService.postComment(recordId, trimmed);
      if (response?.status === 200) {
        const nextComment = {
          comment: trimmed,
          comment_by: authorName,
          created_by: authorName,
          created_at: new Date().toISOString(),
        };
        setComments((prev) => [...prev, nextComment]);
        setDraft('');
        showSnackBar(RECORD_COPY.success.commentAdded, 'success');
        onSuccess?.();
      } else {
        showSnackBar(RECORD_COPY.errors.commentFailed, 'error');
      }
    } catch {
      showSnackBar(RECORD_COPY.errors.commentFailed, 'error');
    } finally {
      setIsSubmitting(false);
    }
  }, [authorName, draft, onSuccess, recordId, showSnackBar]);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      title={RECORD_COPY.comments.title}
      subtitle={subtitle}
      maxWidth="sm"
      contentSx={{
        p: 0,
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
      }}
    >
      <Box
        sx={{
          px: 3,
          py: 2.5,
          minHeight: 280,
          maxHeight: 380,
          overflowY: 'auto',
          bgcolor: semantic.surfaces.surfaceSubtle ?? semantic.surfaces.background,
        }}
      >
        {comments.length === 0 ? (
          <EmptyState
            icon={<ChatBubbleOutlineIcon fontSize="inherit" />}
            title={RECORD_COPY.comments.emptyTitle}
            description={RECORD_COPY.comments.emptyDescription}
            sx={{ py: 5 }}
          />
        ) : (
          <Stack spacing={1.5}>
            {comments.map((comment, index) => (
              <CommentThreadItem
                key={`${comment.created_at || 'comment'}-${index}`}
                comment={comment}
                semantic={semantic}
                typography={typography}
                chat={chat}
              />
            ))}
          </Stack>
        )}
      </Box>

      <Box
        sx={{
          px: 3,
          py: 2.5,
          borderTop: `1px solid ${semantic.borders.border}`,
          bgcolor: semantic.surfaces.surface,
        }}
      >
        <Stack spacing={1.25}>
          <FormTextArea
            placeholder={RECORD_COPY.comments.placeholder}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            minRows={2}
            maxRows={6}
            disabled={isSubmitting}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
                event.preventDefault();
                handleSubmit();
              }
            }}
          />

          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={2}>
            <Typography
              sx={{
                fontSize: typography.fontSizeXs ?? '0.75rem',
                color: semantic.text.muted,
              }}
            >
              Ctrl+Enter to send
            </Typography>
            <Button
              variant="primary"
              size="sm"
              icon={<SendIcon />}
              onClick={handleSubmit}
              loading={isSubmitting}
              disabled={!draft.trim()}
            >
              {RECORD_COPY.comments.send}
            </Button>
          </Stack>
        </Stack>
      </Box>
    </Dialog>
  );
}
