export const LEAD_CHAT_INITIAL_STATE = {
  conversation: {
    phoneNumber: '',
    botNumber: '',
    organisationId: '',
    whatsappName: '',
    profileName: '',
    leadId: '',
    userDetail: null,
  },
  messages: [],
  pagination: {
    page: 1,
    hasMore: false,
    totalCount: 0,
  },
  ui: {
    isLoading: false,
    isLoadingOlder: false,
    isSending: false,
    isResolvingBot: false,
    draft: '',
    isMinimized: false,
    composerMode: 'idle',
    error: null,
  },
  bot: {
    options: [],
    showSelector: false,
    source: '',
  },
  socket: {
    connected: false,
  },
};

export function leadChatSessionReducer(state, action) {
  switch (action.type) {
    case 'RESET':
      return { ...LEAD_CHAT_INITIAL_STATE };

    case 'SET_MINIMIZED':
      return {
        ...state,
        ui: { ...state.ui, isMinimized: Boolean(action.payload) },
      };

    case 'SET_RESOLVING_BOT':
      return {
        ...state,
        ui: { ...state.ui, isResolvingBot: Boolean(action.payload), error: null },
      };

    case 'SET_BOT_RESOLUTION':
      return {
        ...state,
        conversation: {
          ...state.conversation,
          botNumber: action.payload.botNumber || '',
        },
        bot: {
          options: action.payload.botOptions || [],
          showSelector: Boolean(action.payload.showSelector),
          source: action.payload.source || '',
        },
        ui: { ...state.ui, isResolvingBot: false, error: action.payload.error || null },
      };

    case 'SET_CONVERSATION':
      return {
        ...state,
        conversation: { ...state.conversation, ...action.payload },
      };

    case 'SET_USER_DETAIL':
      return {
        ...state,
        conversation: {
          ...state.conversation,
          userDetail: action.payload,
        },
        ui: {
          ...state.ui,
          composerMode: action.payload?.composerMode || state.ui.composerMode,
        },
      };

    case 'SET_COMPOSER_MODE':
      return {
        ...state,
        ui: { ...state.ui, composerMode: action.payload },
      };

    case 'SET_DRAFT':
      return {
        ...state,
        ui: { ...state.ui, draft: action.payload },
      };

    case 'SET_LOADING':
      return {
        ...state,
        ui: { ...state.ui, isLoading: Boolean(action.payload) },
      };

    case 'SET_LOADING_OLDER':
      return {
        ...state,
        ui: { ...state.ui, isLoadingOlder: Boolean(action.payload) },
      };

    case 'SET_SENDING':
      return {
        ...state,
        ui: { ...state.ui, isSending: Boolean(action.payload) },
      };

    case 'SET_MESSAGES':
      return {
        ...state,
        messages: action.payload.messages,
        pagination: {
          ...state.pagination,
          ...action.payload.pagination,
        },
      };

    case 'PREPEND_MESSAGES':
      return {
        ...state,
        messages: [...action.payload, ...state.messages],
        pagination: {
          ...state.pagination,
          page: state.pagination.page + 1,
        },
      };

    case 'APPEND_MESSAGE':
      return {
        ...state,
        messages: [...state.messages, action.payload],
      };

    case 'REMOVE_MESSAGE':
      return {
        ...state,
        messages: state.messages.filter(
          (message) => message.msg_id !== action.payload && message.id !== action.payload
        ),
      };

    case 'REPLACE_MESSAGES':
      return {
        ...state,
        messages: action.payload,
      };

    case 'SET_ERROR':
      return {
        ...state,
        ui: { ...state.ui, error: action.payload },
      };

    default:
      return state;
  }
}
