export function getSocketLeadId(lead) {
  if (!lead || typeof lead !== 'object') return '';
  const id = lead.lead_id ?? lead.id ?? lead._id ?? lead.record_id;
  return id == null ? '' : String(id);
}

export function getLeadAssignmentList(lead) {
  if (!lead || typeof lead !== 'object') return [];
  const assignments = lead.lead_assignment ?? lead._rawLead?.lead_assignment;
  return Array.isArray(assignments) ? assignments : [];
}

export function extractIsCampaignOwner(raw) {
  if (!raw || typeof raw !== 'object') return false;
  if (typeof raw.is_campaign_owner === 'boolean') return raw.is_campaign_owner;
  const nested = raw.data;
  if (nested && typeof nested === 'object' && typeof nested.is_campaign_owner === 'boolean') {
    return nested.is_campaign_owner;
  }
  return false;
}

export function canViewSocketLead(lead, {
  currentUserId,
  isCampaignOwner = false,
  campaignId,
  formId,
} = {}) {
  if (!lead || typeof lead !== 'object') return false;

  const leadCampaignId = lead.campaign_id ?? lead._rawLead?.campaign_id;
  const leadFormId = lead.leads_form_id ?? lead._rawLead?.leads_form_id;

  if (
    campaignId != null
    && campaignId !== ''
    && leadCampaignId != null
    && String(leadCampaignId) !== String(campaignId)
  ) {
    return false;
  }

  if (
    formId != null
    && formId !== ''
    && leadFormId != null
    && String(leadFormId) !== String(formId)
  ) {
    return false;
  }

  if (isCampaignOwner) return true;

  const userId = currentUserId == null || currentUserId === '' ? '' : String(currentUserId);
  if (!userId) return false;

  return getLeadAssignmentList(lead).some((item) => {
    const assignedTo = item?.lead_assigned_to ?? item?.id ?? item?.user_id;
    return assignedTo != null && String(assignedTo) === userId;
  });
}

export function filterVisibleSocketLeads(leads, visibility) {
  return (Array.isArray(leads) ? leads : []).filter((lead) => canViewSocketLead(lead, visibility));
}

export function addUnreadLeadIds(unreadLeadIds, ids) {
  const next = new Set(unreadLeadIds);
  (ids instanceof Set ? [...ids] : ids || []).forEach((id) => {
    if (id) next.add(String(id));
  });
  return next;
}

export function removeUnreadLeadIds(unreadLeadIds, ids) {
  const next = new Set(unreadLeadIds);
  (ids instanceof Set ? [...ids] : ids || []).forEach((id) => {
    if (id) next.delete(String(id));
  });
  return next;
}

export function applySocketRowsToTable({
  notificationType,
  incomingRows = [],
  prevRows = [],
  prevTotalCount = 0,
  unreadLeadIds = new Set(),
} = {}) {
  const incoming = Array.isArray(incomingRows) ? incomingRows : [];
  const previous = Array.isArray(prevRows) ? prevRows : [];
  const previousUnread = unreadLeadIds instanceof Set ? unreadLeadIds : new Set(unreadLeadIds || []);

  if (notificationType === 'delete_leads') {
    const remoteIds = new Set(incoming.map(getSocketLeadId).filter(Boolean));
    if (!remoteIds.size) {
      return {
        rows: previous,
        totalCount: prevTotalCount,
        unreadLeadIds: previousUnread,
        insertedCount: 0,
      };
    }

    const rows = previous.filter((row) => !remoteIds.has(getSocketLeadId(row)));
    const removed = previous.length - rows.length;
    return {
      rows,
      totalCount: Math.max((prevTotalCount || 0) - removed, 0),
      unreadLeadIds: removeUnreadLeadIds(previousUnread, remoteIds),
      insertedCount: 0,
    };
  }

  if (!incoming.length) {
    return {
      rows: previous,
      totalCount: prevTotalCount,
      unreadLeadIds: previousUnread,
      insertedCount: 0,
    };
  }

  if (notificationType === 'new_leads') {
    const incomingIds = new Set(incoming.map(getSocketLeadId).filter(Boolean));
    const existingIds = new Set(previous.map(getSocketLeadId));
    const newIds = [...incomingIds].filter((id) => !existingIds.has(id));
    const kept = previous.filter((row) => !incomingIds.has(getSocketLeadId(row)));

    return {
      rows: [...incoming, ...kept],
      totalCount: (prevTotalCount || 0) + newIds.length,
      unreadLeadIds: addUnreadLeadIds(previousUnread, incomingIds),
      insertedCount: newIds.length,
    };
  }

  if (notificationType === 'update_leads' || notificationType === 'bulk_update_leads') {
    const next = [...previous];
    const inserted = [];

    incoming.forEach((row) => {
      const id = getSocketLeadId(row);
      const idx = next.findIndex((item) => getSocketLeadId(item) === id);
      if (idx >= 0) {
        next[idx] = { ...next[idx], ...row };
        return;
      }
      next.unshift(row);
      if (id) inserted.push(id);
    });

    return {
      rows: next,
      totalCount: (prevTotalCount || 0) + inserted.length,
      unreadLeadIds: inserted.length
        ? addUnreadLeadIds(previousUnread, inserted)
        : previousUnread,
      insertedCount: inserted.length,
    };
  }

  return {
    rows: previous,
    totalCount: prevTotalCount,
    unreadLeadIds: previousUnread,
    insertedCount: 0,
  };
}
