import React from 'react';
import { Box } from '@mui/material';
import TemplateSendPreview from '../../../whatsapp-templates/components/send/TemplateSendPreview';

export default function LeadSendTemplatePreviewPanel({ template, bodyParams = [] }) {
  if (!template) return null;

  return (
    <Box
      sx={{
        minWidth: 0,
        width: '100%',
        '& .MuiChip-root': {
          height: 22,
          fontSize: '0.6875rem',
          fontWeight: 600,
        },
        '& .MuiChip-label': {
          px: 0.875,
        },
      }}
    >
      <TemplateSendPreview template={template} bodyParams={bodyParams} compact />
    </Box>
  );
}
