import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useRecoilValue } from 'recoil';
import { userInformationAtom } from '../../../../Services/_states';
import { dateFormate } from '../../../../utils/helper.jsx';
import { recordService } from '../services/recordService';
import {
  applySavedFiltersToArray,
  buildInitialFiltersArray,
  buildTypeOfStatusList,
  hydrateFiltersWithStatusOptions,
  isActiveDynamicFilter,
  mergeDynamicFilterRules,
  resetFiltersArray,
  transformDynamicFilters,
} from '../utils/dynamicFilterUtils';

const EMPTY_DATE_RANGE = { startDate: null, endDate: null };

function normalizeAssignedUsers(users = []) {
  return users.map((user) => ({
    ...user,
    label: user.username
      || `${user.first_name || ''} ${user.last_name || ''}`.trim()
      || user.email,
    value: user.id ?? user.profile_id ?? null,
  }));
}

export default function useDynamicFilters({
  open,
  formItems,
  tableId,
  workspaceId,
  appliedFilters = {},
  isCampaignOwner = true,
}) {
  const loggedInUser = useRecoilValue(userInformationAtom);
  const orgId = loggedInUser?.profile?.organisation?.organisation_id;

  const [filtersArray, setFiltersArray] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [assignedUsersList, setAssignedUsersList] = useState([]);
  const [loadingAssignedUsers, setLoadingAssignedUsers] = useState(false);
  const [statusObj, setStatusObj] = useState(null);
  const [assigneeObj, setAssigneeObj] = useState(null);
  const [dateRange, setDateRange] = useState(EMPTY_DATE_RANGE);

  const formItemsRef = useRef(formItems);
  formItemsRef.current = formItems;

  const appliedFiltersRef = useRef(appliedFilters);
  appliedFiltersRef.current = appliedFilters;

  const loadSessionRef = useRef(null);

  const typeOfStatusList = useMemo(
    () => buildTypeOfStatusList(statusList),
    [statusList]
  );

  useEffect(() => {
    if (!open) {
      loadSessionRef.current = null;
      return;
    }

    const initial = buildInitialFiltersArray(formItemsRef.current);
    setFiltersArray(applySavedFiltersToArray(initial, appliedFiltersRef.current));
    setStatusObj(appliedFiltersRef.current.statusObj || null);
    setAssigneeObj(appliedFiltersRef.current.assigneeObj || null);
    setDateRange({
      startDate: appliedFiltersRef.current.start_date
        ? new Date(appliedFiltersRef.current.start_date)
        : null,
      endDate: appliedFiltersRef.current.end_date
        ? new Date(appliedFiltersRef.current.end_date)
        : null,
    });
  }, [open, tableId]);

  useEffect(() => {
    if (!open) return;

    const sessionKey = `${tableId || ''}:${workspaceId || ''}:${orgId || ''}:${isCampaignOwner}`;
    if (loadSessionRef.current === sessionKey) return;
    loadSessionRef.current = sessionKey;

    let cancelled = false;
    setLoadingAssignedUsers(Boolean(orgId && isCampaignOwner));

    const loadFilterOptions = async () => {
      const [statuses, users] = await Promise.all([
        tableId ? recordService.fetchStatusList(tableId) : Promise.resolve([]),
        orgId && isCampaignOwner
          ? recordService.fetchAssignedUsers(orgId, workspaceId)
          : Promise.resolve([]),
      ]);

      if (cancelled) return;

      const nextStatuses = Array.isArray(statuses) ? statuses : [];
      setStatusList(nextStatuses);
      setAssignedUsersList(normalizeAssignedUsers(users));
      setLoadingAssignedUsers(false);

      setFiltersArray((prev) => {
        const base = prev.length
          ? prev
          : applySavedFiltersToArray(
            buildInitialFiltersArray(formItemsRef.current),
            appliedFiltersRef.current
          );

        if (!base.length || !nextStatuses.length) return base;
        return hydrateFiltersWithStatusOptions(base, formItemsRef.current, nextStatuses);
      });
    };

    loadFilterOptions();

    return () => {
      cancelled = true;
    };
  }, [open, tableId, workspaceId, orgId, isCampaignOwner]);

  const updateFilter = useCallback((index, updates) => {
    setFiltersArray((prev) => prev.map((filter, idx) => (
      idx === index ? { ...filter, ...updates } : filter
    )));
  }, []);

  const buildAppliedFilters = useCallback(() => {
    const startDate = dateRange.startDate
      ? dateFormate(dateRange.startDate, 'YYYY-MM-DD')
      : '';
    const endDate = dateRange.endDate
      ? dateFormate(dateRange.endDate, 'YYYY-MM-DD')
      : '';

    const activeFilters = filtersArray.filter(isActiveDynamicFilter);
    const previous = Array.isArray(appliedFilters.dynamicFilters)
      ? appliedFilters.dynamicFilters
      : [];
    const current = transformDynamicFilters(activeFilters);
    const mergedDynamicFilters = mergeDynamicFilterRules(previous, current);

    return {
      start_date: startDate,
      end_date: endDate,
      statusObj: statusObj || null,
      status: statusObj?.status_name || '',
      assigneeObj: isCampaignOwner ? assigneeObj || null : null,
      lead_assigned_to: isCampaignOwner ? (assigneeObj?.id ?? '') : '',
      is_pending: appliedFilters.is_pending ?? '',
      dynamicFilters: mergedDynamicFilters,
    };
  }, [
    appliedFilters.dynamicFilters,
    appliedFilters.is_pending,
    assigneeObj,
    dateRange.endDate,
    dateRange.startDate,
    filtersArray,
    isCampaignOwner,
    statusObj,
  ]);

  const buildEmptyFilters = useCallback(() => ({
    start_date: '',
    end_date: '',
    status: '',
    lead_assigned_to: '',
    is_pending: '',
    statusObj: null,
    assigneeObj: null,
    dynamicFilters: [],
  }), []);

  const handleApply = useCallback(() => {
    const activeFilters = filtersArray.filter(isActiveDynamicFilter);
    const hasAnyFilter =
      activeFilters.length > 0
      || dateRange.startDate
      || dateRange.endDate
      || statusObj
      || (isCampaignOwner && assigneeObj);

    if (!hasAnyFilter) {
      return buildEmptyFilters();
    }

    return buildAppliedFilters();
  }, [
    assigneeObj,
    buildAppliedFilters,
    buildEmptyFilters,
    dateRange.endDate,
    dateRange.startDate,
    filtersArray,
    isCampaignOwner,
    statusObj,
  ]);

  const handleClear = useCallback(() => {
    setFiltersArray((prev) => resetFiltersArray(prev));
    setDateRange(EMPTY_DATE_RANGE);
    setStatusObj(null);
    setAssigneeObj(null);
    return buildEmptyFilters();
  }, [buildEmptyFilters]);

  return {
    filtersArray,
    typeOfStatusList,
    statusList,
    assignedUsersList,
    loadingAssignedUsers,
    statusObj,
    setStatusObj,
    assigneeObj,
    setAssigneeObj,
    dateRange,
    setDateRange,
    updateFilter,
    handleApply,
    handleClear,
    isCampaignOwner,
  };
}
