import { userOwnsChat } from '../../../../intervene/utils/chatOwnership';

export function isLeadChatSessionActive(user) {
  return Boolean(user?.intervene && user?.session_start);
}

export function isChatLockedByOtherUser(user, currentUserId) {
  if (!isLeadChatSessionActive(user)) return false;
  return !userOwnsChat(user, currentUserId);
}

export function getIntervenedAgentLabel(user) {
  const label = user?.intervened_by;
  return typeof label === 'string' && label.trim() ? label.trim() : 'Another agent';
}

export function getLastIntervenedAgentLabel(user) {
  const label = user?.last_intervened_by;
  return typeof label === 'string' && label.trim() ? label.trim() : '';
}

export function canShowSessionToggle(user, currentUserId) {
  return !isChatLockedByOtherUser(user, currentUserId);
}

export function canStartLeadChatSession(user, currentUserId) {
  if (isLeadChatSessionActive(user)) return false;
  return true;
}

export function canEndLeadChatSession(user, currentUserId) {
  if (!isLeadChatSessionActive(user)) return false;
  return userOwnsChat(user, currentUserId);
}

export function buildSessionTogglePayload({
  phoneNumber,
  botNumber,
  organisationId,
  whatsappName,
  user,
  start,
  leadId,
  recordId,
  leadsFormId,
}) {
  return {
    phone_number: phoneNumber,
    bot_number: botNumber,
    intervene: start,
    session_start: start,
    ...(organisationId ? { company_id: organisationId } : {}),
    ...(whatsappName ? { whatsapp_name: whatsappName } : {}),
    ...(user?.session_id ? { session_id: user.session_id } : {}),
    ...(leadId ? { lead_id: leadId } : {}),
    ...(recordId ? { record_id: recordId } : {}),
    ...(leadsFormId ? { leads_form_id: leadsFormId } : {}),
  };
}
