import React from 'react';
import { Box, Typography } from '@mui/material';
import MediaMessage from './MediaMessage';
import DocumentMessage from './DocumentMessage';

export default function TemplateMessage({ message }) {
  const header = message.header;
  const body = message.text || message.templateName || 'Template message';

  return (
    <Box sx={{ maxWidth: 240 }}>
      {header?.kind === 'image' || header?.kind === 'video' ? (
        <Box sx={{ mb: body ? 0.75 : 0 }}>
          <MediaMessage
            message={{
              kind: header.kind,
              media: { kind: header.kind, url: header.url },
            }}
          />
        </Box>
      ) : null}
      {header?.kind === 'document' ? (
        <Box sx={{ mb: body ? 0.75 : 0 }}>
          <DocumentMessage
            message={{
              kind: 'document',
              media: { kind: 'document', url: header.url, fileName: header.fileName },
            }}
          />
        </Box>
      ) : null}
      {body ? (
        <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
          {body}
        </Typography>
      ) : null}
    </Box>
  );
}
