import React, { useMemo } from 'react';
import { Box, CircularProgress, Typography } from '@mui/material';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import { groupLeadChatMessages } from '../utils/groupLeadChatMessages';
import { getMessageKey } from '../utils/leadChatMessageNormalize';
import LeadChatMessageBubble from './messages/LeadChatMessageBubble';
import useLeadChatSx from '../hooks/useLeadChatSx';

export default function LeadChatMessageFeed({
  scrollRef,
  onScroll,
  messages,
  isLoading,
  isLoadingOlder,
}) {
  const sx = useLeadChatSx();
  const grouped = useMemo(() => groupLeadChatMessages(messages), [messages]);

  return (
    <Box ref={scrollRef} onScroll={onScroll} sx={sx.feed}>
      {isLoadingOlder ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 1 }}>
          <CircularProgress size={18} />
          <Typography variant="caption" sx={{ ml: 1 }}>
            {LEAD_CHAT_COPY.feed.loadingOlder}
          </Typography>
        </Box>
      ) : null}

      {isLoading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flex: 1, py: 4 }}>
          <CircularProgress size={24} />
          <Typography variant="body2" sx={{ ml: 1.5 }}>
            {LEAD_CHAT_COPY.feed.loading}
          </Typography>
        </Box>
      ) : null}

      {!isLoading && !messages.length ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flex: 1, px: 2 }}>
          <Typography variant="body2" color="text.secondary" align="center">
            {LEAD_CHAT_COPY.feed.empty}
          </Typography>
        </Box>
      ) : null}

      {!isLoading
        ? grouped.map(({ message, isFirstInGroup, isLastInGroup }, index) => (
          <LeadChatMessageBubble
            key={getMessageKey(message, index)}
            message={message}
            isFirstInGroup={isFirstInGroup}
            isLastInGroup={isLastInGroup}
          />
        ))
        : null}
    </Box>
  );
}
