import {
  getBulkSheetParamColumns,
  getBulkSheetRequiredColumns,
  normalizeExcelCell,
  parseBulkExcelFile,
  stripUploadSheetColumns,
  validateBulkPhoneNumber,
  validateBulkSheetColumns,
} from '../../../whatsapp-templates/utils/bulkSheetValidation';

const MAX_INLINE_ERRORS = 25;

function buildRowError(field, code, message) {
  return { field, code, message };
}

export function validateLeadTemplateSheetRows(rows, template) {
  const paramColumns = getBulkSheetParamColumns(template);
  const rowResults = [];

  rows.forEach((rawRow, rowIndex) => {
    const row = stripUploadSheetColumns(rawRow);
    const rowNumber = row.row_number != null && row.row_number !== ''
      ? Number(row.row_number)
      : rowIndex + 2;
    const errors = [];

    const phoneResult = validateBulkPhoneNumber(row.phone_number);
    if (!phoneResult.valid) {
      errors.push(buildRowError('phone_number', 'invalid_phone', phoneResult.error));
    }

    paramColumns.forEach((col) => {
      if (col === 'phone_number') return;
      if (!normalizeExcelCell(row[col])) {
        errors.push(
          buildRowError(col, 'required', `"${col}" is empty (required)`)
        );
      }
    });

    rowResults.push({
      rowIndex,
      rowNumber,
      row,
      errors,
    });
  });

  const invalidRows = rowResults.filter((entry) => entry.errors.length > 0);
  const inlineMessages = invalidRows
    .slice(0, MAX_INLINE_ERRORS)
    .map((entry) => {
      const summary = entry.errors.map((error) => error.message).join('; ');
      return `Row ${entry.rowNumber}: ${summary}`;
    });

  if (invalidRows.length > MAX_INLINE_ERRORS) {
    inlineMessages.push('...and more errors. Fix the above and re-upload.');
  }

  return {
    valid: invalidRows.length === 0,
    rowResults,
    invalidRows,
    inlineMessages,
  };
}

export async function validateLeadTemplateSheetFile(file, template) {
  const requiredColumns = getBulkSheetRequiredColumns(template);

  if (!file) {
    return {
      valid: false,
      fileErrors: ['No file selected'],
      columnErrors: [],
      rowResults: [],
      inlineMessages: ['No file selected'],
    };
  }

  let rows;
  try {
    rows = await parseBulkExcelFile(file);
  } catch (error) {
    return {
      valid: false,
      fileErrors: [error?.message || 'Failed to read Excel file'],
      columnErrors: [],
      rowResults: [],
      inlineMessages: [error?.message || 'Failed to read Excel file'],
    };
  }

  if (!rows.length) {
    return {
      valid: false,
      fileErrors: ['Excel file has no data rows'],
      columnErrors: [],
      rowResults: [],
      inlineMessages: ['Excel file has no data rows'],
    };
  }

  const columnErrors = validateBulkSheetColumns(rows, requiredColumns, { strict: true });
  if (columnErrors.length) {
    const message = columnErrors.join('\n');
    return {
      valid: false,
      fileErrors: [],
      columnErrors,
      rowResults: [],
      inlineMessages: columnErrors,
    };
  }

  const rowValidation = validateLeadTemplateSheetRows(rows, template);
  return {
    valid: rowValidation.valid,
    fileErrors: [],
    columnErrors: [],
    rowResults: rowValidation.rowResults,
    invalidRows: rowValidation.invalidRows,
    inlineMessages: rowValidation.inlineMessages,
  };
}
