export function normalizeMessagesResponse(res) {
  const data = res?.data || {};
  return {
    messages: Array.isArray(data.data) ? data.data : [],
    totalCount: Number(data.total_count) || 0,
  };
}

export function normalizeLeadChatUserDetail(sessionRes, { phoneNumber, botNumber, whatsappName }) {
  const data = sessionRes?.data;
  const source = data && typeof data === 'object' && !Array.isArray(data) ? data : {};

  return {
    ...source,
    phone_number: source.phone_number || phoneNumber,
    bot_number: source.bot_number || botNumber,
    whatsapp_name: source.whatsapp_name || whatsappName || '',
    intervene: Boolean(source.intervene),
    session_start: Boolean(source.session_start),
    last_active_date: source.last_active_date || source.updated_at || null,
    intervened_by: source.intervened_by || '',
    intervened_by_user_id: source.intervened_by_user_id ?? null,
    last_intervened_by: source.last_intervened_by || '',
    last_intervened_by_user_id: source.last_intervened_by_user_id ?? null,
    last_intervened_at: source.last_intervened_at || null,
  };
}

export function normalizeBotListResponse(res) {
  if (!res || (res.status !== 200 && res.status !== 201)) return [];

  let source = [];
  if (Array.isArray(res?.data)) {
    source = res.data;
  } else if (Array.isArray(res?.data?.data)) {
    source = res.data.data;
  } else if (Array.isArray(res?.data?.list)) {
    source = res.data.list;
  } else if (Array.isArray(res?.data?.results)) {
    source = res.data.results;
  }

  return source
    .map((item) => {
      const waPhone =
        item?.wa_phone_number ||
        item?.channel_number ||
        item?.bot_number ||
        item?.phone_number ||
        '';
      if (!waPhone) return null;
      return {
        ...item,
        wa_phone_number: String(waPhone),
        app_name: item?.app_name || item?.display_name || item?.source_name || '',
      };
    })
    .filter(Boolean);
}
