import React, { useEffect, useState } from 'react';
import { Box, Chip, CircularProgress, Grid, TextField, Typography } from '@mui/material';
import { useRecoilValue } from 'recoil';
import DynamicFormFieldsList from '../../../../components/Leads/DynamicFormFields/List.tsx';
import { FormDrawer } from '../../../../components/ui';
import { userInformationAtom } from '../../../../Services/_states';
import { RECORD_COPY } from '../constants/recordCopy';

export default function RecordDrawer({
  open,
  mode,
  selectedRecord,
  dynamicFormData,
  fieldErrors,
  formEnable,
  formDataLoading,
  isLoading,
  isFormDirty,
  isReadOnly,
  isCreating,
  hasFormFields,
  onClose,
  onFieldChange,
  onSave,
  onEdit,
  onPhoneNumberChange, // optional: parent can still listen if it wants
  multipleFormUpdate = false,
}) {
  const loggedInUser = useRecoilValue(userInformationAtom);
  const profileId = loggedInUser?.profile?.id ?? loggedInUser?.id;

  // 🔹 local state — same pattern as FormDetailsModal, doesn't depend on parent wiring
  const [phoneNumber, setPhoneNumber] = useState('');
  const [phoneNumberError, setPhoneNumberError] = useState('');

  useEffect(() => {
    if (!open) return;
    setPhoneNumber(selectedRecord?.phone_number || '');
    setPhoneNumberError('');
  }, [open, selectedRecord]);

  const title = isCreating
    ? RECORD_COPY.drawer.createTitle
    : isReadOnly
      ? RECORD_COPY.drawer.viewTitle
      : RECORD_COPY.drawer.editTitle;

  const subtitle = isCreating
    ? RECORD_COPY.drawer.createSubtitle
    : selectedRecord?.lead_id
      ? `Lead ${selectedRecord.lead_id}`
      : undefined;

  const submitLabel = isReadOnly ? RECORD_COPY.drawer.edit : RECORD_COPY.drawer.save;
  const showFooter = !formDataLoading && (isCreating || hasFormFields);
  const showPhoneField = !multipleFormUpdate && (isCreating || hasFormFields);
  const showDynamicFields =
    hasFormFields || (isCreating && Boolean(Object.keys(dynamicFormData || {}).length));
  const showEmptyState = !formDataLoading && !isCreating && !hasFormFields;

  const phoneDisabled =
    isReadOnly || Boolean(selectedRecord?.lead_id && selectedRecord?.phone_number) || formEnable;

  const handlePhoneChange = (e) => {
    const value = e.target.value.replace(/\D/g, '');
    setPhoneNumber(value);
    setPhoneNumberError('');
    onPhoneNumberChange?.(value); // bubble up for parent save-payload, if it listens
  };

  const validatePhone = () => {
    if (!phoneNumber) {
      setPhoneNumberError('Phone number is required.');
      return false;
    }
    if (/[^0-9]/.test(phoneNumber)) {
      setPhoneNumberError('Phone number should only contain digits.');
      return false;
    }
    if (phoneNumber.length < 10) {
      setPhoneNumberError('Phone number must be at least 10 digits long.');
      return false;
    }
    return true;
  };

  const handleSubmit = () => {
    if (isReadOnly) {
      onEdit?.();
      return;
    }
    if (!multipleFormUpdate && !validatePhone()) return;
    onSave?.(phoneNumber); // pass phoneNumber along so parent can put it in the payload
  };

  return (
    <FormDrawer
      open={open}
      onClose={onClose}
      title={title}
      subtitle={subtitle}
      headerBadge={
        isCreating ? (
          <Chip label="New" size="small" color="success" sx={{ borderRadius: 0 }} />
        ) : isReadOnly ? (
          <Chip label="Read only" size="small" sx={{ borderRadius: 0 }} />
        ) : (
          <Chip label="Editing" size="small" color="warning" sx={{ borderRadius: 0 }} />
        )
      }
      onSubmit={showFooter ? handleSubmit : undefined}
      isSubmitting={isLoading}
      submitLabel={submitLabel}
      cancelLabel={RECORD_COPY.drawer.cancel}
      confirmBeforeClose={isFormDirty && !isReadOnly}
      showFooter={showFooter}
      disableClose={isLoading}
    >
      {formDataLoading ? (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, py: 4 }}>
          <CircularProgress size={24} />
          <Typography variant="body2" color="text.secondary">
            Loading record form…
          </Typography>
        </Box>
      ) : showEmptyState ? (
        <Typography variant="body2" color="text.secondary">
          No editable fields are configured for this form.
        </Typography>
      ) : (
        <>
          {showPhoneField ? (
            <Grid container spacing={2} sx={{ mb: 2 }}>
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  fullWidth
                  label={
                    <Typography component="span">
                      Phone Number <span style={{ color: 'red' }}>*</span>
                    </Typography>
                  }
                  placeholder="Enter Mobile Number"
                  variant="outlined"
                  size="small"
                  value={phoneNumber}
                  disabled={phoneDisabled}
                  onChange={handlePhoneChange}
                  error={!!phoneNumberError}
                  helperText={phoneNumberError || ''}
                  inputProps={{
                    maxLength: 12,
                    inputMode: 'numeric',
                    pattern: '[0-9]*',
                  }}
                />
              </Grid>
            </Grid>
          ) : null}

          {showDynamicFields ? (
            <DynamicFormFieldsList
              data={dynamicFormData || {}}
              userId={profileId}
              onChange={onFieldChange}
              fieldErrors={fieldErrors}
              disabled={formEnable}
              phoneNumber={phoneNumber}
              gridSize={12}
              variant="compact"
              isCreatingLead={isCreating}
            />
          ) : null}
        </>
      )}
    </FormDrawer>
  );
}