export const LEAD_CHAT_SESSION_WINDOW_SECONDS = 24 * 60 * 60;

export function parseLastActiveDate(value) {
  if (value == null || value === '') return null;

  if (typeof value === 'number') {
    const date = new Date(value > 9999999999 ? value : value * 1000);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  const str = String(value).trim();
  const withZone = str.includes('Z') || /[+-]\d{2}:\d{2}$/.test(str) ? str : `${str}Z`;
  const date = new Date(withZone);
  if (!Number.isNaN(date.getTime())) return date;

  const fallback = new Date(str);
  return Number.isNaN(fallback.getTime()) ? null : fallback;
}

export function getSessionRemainingSeconds(lastActive) {
  const date = parseLastActiveDate(lastActive);
  if (!date) return 0;
  const diffSec = Math.floor((Date.now() - date.getTime()) / 1000);
  const remaining = LEAD_CHAT_SESSION_WINDOW_SECONDS - diffSec;
  return remaining > 0 ? remaining : 0;
}

export function isSessionExpired(lastActive) {
  return getSessionRemainingSeconds(lastActive) === 0;
}

export function getLastActiveFromUser(user) {
  if (!user) return null;
  return (
    user.last_active_date
    || user.updated_at
    || user.last_message?.created_at
    || user.last_active
    || null
  );
}
