import { useCallback, useMemo, useState } from 'react';
import SweetAlert from '../../../../../components/Shared/Notification';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import { buildLeadChatBaseContext } from '../utils/leadChatContext';
import { resolveLeadPhoneFromRow } from '../../utils/leadTemplateSendUtils';

export default function useLeadChat({ formPayload, organisationId, leadsFormId } = {}) {
  const [isOpen, setIsOpen] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [selectedRow, setSelectedRow] = useState(null);

  const baseContext = useMemo(
    () => (
      selectedRow
        ? buildLeadChatBaseContext(selectedRow, organisationId, leadsFormId)
        : null
    ),
    [leadsFormId, organisationId, selectedRow]
  );

  const openLeadChat = useCallback((row) => {
    const phoneResult = resolveLeadPhoneFromRow(row);
    if (!phoneResult.valid) {
      SweetAlert(LEAD_CHAT_COPY.errors.phoneInvalid, 'error');
      return false;
    }

    if (!organisationId) {
      SweetAlert(LEAD_CHAT_COPY.errors.orgMissing, 'error');
      return false;
    }

    setSelectedRow(row);
    setIsOpen(true);
    setIsMinimized(false);
    return true;
  }, [organisationId]);

  const closeLeadChat = useCallback(() => {
    setIsOpen(false);
    setIsMinimized(false);
    setSelectedRow(null);
  }, []);

  const minimizeLeadChat = useCallback(() => {
    setIsMinimized(true);
  }, []);

  const restoreLeadChat = useCallback(() => {
    setIsMinimized(false);
  }, []);

  return {
    isOpen,
    isMinimized,
    selectedRow,
    baseContext,
    formPayload,
    organisationId,
    openLeadChat,
    closeLeadChat,
    minimizeLeadChat,
    restoreLeadChat,
  };
}
