import React from 'react';
import { Box, Button, Typography } from '@mui/material';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import { isComposerExpired, isComposerIdle, isComposerLocked } from '../utils/leadChatComposerMode';
import {
  getIntervenedAgentLabel,
  getLastIntervenedAgentLabel,
} from '../utils/leadChatSessionRules';
import useLeadChatSx from '../hooks/useLeadChatSx';

export default function LeadChatSessionBanner({
  composerMode,
  userDetail = null,
  canSendTemplate = false,
  onStartSession,
  onOpenSendTemplate,
}) {
  const sx = useLeadChatSx();

  if (isComposerLocked(composerMode)) {
    return (
      <Box sx={sx.sessionBanner}>
        <Typography sx={sx.sessionBannerText}>
          {LEAD_CHAT_COPY.composer.lockedTitle(getIntervenedAgentLabel(userDetail))}
        </Typography>
      </Box>
    );
  }

  if (isComposerIdle(composerMode)) {
    const lastHandledBy = getLastIntervenedAgentLabel(userDetail);
    return (
      <Box sx={sx.sessionBanner}>
        <Typography sx={sx.sessionBannerText}>
          {LEAD_CHAT_COPY.composer.idleTitle}
          {lastHandledBy
            ? ` ${LEAD_CHAT_COPY.composer.idleLastHandled(lastHandledBy)}`
            : ''}
        </Typography>
        <Button sx={sx.sessionBannerAction} onClick={onStartSession}>
          {LEAD_CHAT_COPY.composer.idleAction}
        </Button>
      </Box>
    );
  }

  if (isComposerExpired(composerMode)) {
    return (
      <Box sx={sx.sessionBanner}>
        <Typography sx={sx.sessionBannerText}>
          {LEAD_CHAT_COPY.composer.expiredTitle}
        </Typography>
        {canSendTemplate ? (
          <Button sx={sx.sessionBannerAction} onClick={onOpenSendTemplate}>
            {LEAD_CHAT_COPY.composer.expiredAction}
          </Button>
        ) : null}
      </Box>
    );
  }

  return null;
}
