import { getTemplateParamNames, resolveParamValue } from './leadTemplateParamMapper';
import { resolveLeadPhoneFromRow } from './leadTemplateSendUtils';

export const COVERAGE_STATUS = Object.freeze({
  AGENT: 'agent',
  TABLE: 'table',
  PARTIAL: 'partial',
  MISSING: 'missing',
});

function classifyParam(paramName) {
  const raw = String(paramName ?? '');
  if (raw.startsWith('agent_')) return COVERAGE_STATUS.AGENT;
  return COVERAGE_STATUS.TABLE;
}

export function analyzeParamCoverage(template, selectedRows = [], columnsMeta = [], loggedInUser = null) {
  const params = getTemplateParamNames(template);
  const totalRows = selectedRows.length;

  const items = params.map(({ name, label }) => {
    const baseStatus = classifyParam(name);
    if (baseStatus === COVERAGE_STATUS.AGENT) {
      const agentValue = resolveParamValue(name, selectedRows[0] ?? {}, loggedInUser, columnsMeta);
      return {
        paramName: name,
        label,
        status: agentValue ? COVERAGE_STATUS.AGENT : COVERAGE_STATUS.PARTIAL,
        filledCount: agentValue ? totalRows : 0,
        totalRows,
      };
    }

    let filledCount = 0;
    selectedRows.forEach((row) => {
      const value = resolveParamValue(name, row, loggedInUser, columnsMeta);
      if (String(value ?? '').trim()) {
        filledCount += 1;
      }
    });

    let status = COVERAGE_STATUS.MISSING;
    if (filledCount === totalRows && totalRows > 0) {
      status = COVERAGE_STATUS.TABLE;
    } else if (filledCount > 0) {
      status = COVERAGE_STATUS.PARTIAL;
    }

    return {
      paramName: name,
      label,
      status,
      filledCount,
      totalRows,
    };
  });

  const hasMissing = items.some((item) => item.status === COVERAGE_STATUS.MISSING);
  const hasPartial = items.some((item) => item.status === COVERAGE_STATUS.PARTIAL);
  const isSingleRecipient = totalRows === 1;
  const recommendedTab =
    isSingleRecipient || (!hasMissing && !hasPartial) ? 'direct' : 'sheet';

  const phoneSummary = selectedRows.reduce(
    (acc, row) => {
      if (resolveLeadPhoneFromRow(row).valid) {
        acc.withPhone += 1;
      } else {
        acc.withoutPhone += 1;
      }
      return acc;
    },
    { withPhone: 0, withoutPhone: 0 }
  );

  return {
    items,
    hasMissing,
    hasPartial,
    isSingleRecipient,
    recommendedTab,
    phoneSummary,
  };
}
