import React from 'react';
import { Tooltip } from '@mui/material';
import { Button } from '../../../../components/ui';
import useFeatureTheme from '../../../../theme/hooks/useFeatureTheme';

/**
 * Themed icon-only toolbar control — matches outline Button styling used in records toolbar.
 */
export default function RecordToolbarIconButton({
  title,
  ariaLabel,
  onClick,
  icon,
  disabled = false,
}) {
  const { semantic, controlHeights, typography, radiusPx, shadows } = useFeatureTheme();

  if (!onClick) return null;

  const label = ariaLabel || title;
  const iconSize = Math.max(controlHeights.sm - 14, 16);

  return (
    <Tooltip
      title={title}
      arrow
      placement="top"
      slotProps={{
        tooltip: {
          sx: {
            bgcolor: semantic.text.primary,
            color: semantic.text.inverse,
            fontSize: typography.fontSizeSm,
            fontWeight: typography.fontWeightMedium,
            borderRadius: radiusPx.sm,
            px: 1.25,
            py: 0.5,
            boxShadow: shadows.sm,
          },
        },
        arrow: {
          sx: {
            color: semantic.text.primary,
          },
        },
      }}
    >
      <span>
        <Button
          variant="outline"
          size="sm"
          aria-label={label}
          onClick={onClick}
          disabled={disabled}
          icon={icon}
          sx={{
            minWidth: controlHeights.sm,
            width: controlHeights.sm,
            height: controlHeights.sm,
            px: 0,
            '& .MuiSvgIcon-root': {
              fontSize: iconSize,
            },
          }}
        />
      </span>
    </Tooltip>
  );
}
