import React, { useMemo } from 'react';
import { Box, Typography } from '@mui/material';
import DoneIcon from '@mui/icons-material/Done';
import DoneAllIcon from '@mui/icons-material/DoneAll';
import { normalizeLeadChatMessage } from '../../utils/leadChatMessageNormalize';
import { getLeadChatBubbleShape } from '../../utils/leadChatBubbleShape';
import LeadChatMessageBody from './LeadChatMessageBody';
import useLeadChatSx from '../../hooks/useLeadChatSx';

function formatTime(dateValue) {
  try {
    return new Date(dateValue).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  } catch {
    return '';
  }
}

function StatusIcon({ status, isMine, metaSx }) {
  if (!isMine || !status) return null;
  const normalized = `${status}`.toLowerCase();
  const readColor = normalized === 'read' ? '#53BDEB' : 'inherit';

  if (normalized === 'read') {
    return <DoneAllIcon sx={{ fontSize: 14, color: readColor }} />;
  }
  if (normalized === 'delivered' || normalized === 'sent') {
    return <DoneAllIcon sx={{ fontSize: 14, color: metaSx?.color || 'inherit', opacity: 0.7 }} />;
  }
  return <DoneIcon sx={{ fontSize: 14, color: metaSx?.color || 'inherit', opacity: 0.7 }} />;
}

export default function LeadChatMessageBubble({ message, isFirstInGroup, isLastInGroup }) {
  const sx = useLeadChatSx();
  const normalized = useMemo(() => normalizeLeadChatMessage(message), [message]);
  const bubbleSx = normalized.isMine ? sx.bubbleMine : sx.bubbleTheirs;
  const metaSx = normalized.isMine ? sx.bubbleMetaMine : sx.bubbleMetaTheirs;
  const shape = getLeadChatBubbleShape({
    isMine: normalized.isMine,
    isFirstInGroup,
    isLastInGroup,
  });
  const isMediaPrimary = ['image', 'video', 'document'].includes(normalized.kind)
    && Boolean(normalized.media?.url || normalized.mediaUrl)
    && !normalized.text;

  return (
    <Box
      sx={{
        display: 'flex',
        justifyContent: normalized.isMine ? 'flex-end' : 'flex-start',
        mb: isLastInGroup ? 1 : 0.375,
        px: 1.25,
      }}
    >
      <Box
        sx={{
          ...bubbleSx,
          ...shape,
          maxWidth: '78%',
          px: isMediaPrimary ? 0.5 : 1.25,
          py: isMediaPrimary ? 0.5 : 0.625,
        }}
      >
        <LeadChatMessageBody message={normalized} />
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-end',
            gap: 0.375,
            mt: 0.25,
            ml: 1.5,
          }}
        >
          <Typography variant="caption" sx={{ fontSize: 10, lineHeight: 1, ...metaSx }}>
            {formatTime(normalized.timestamp)}
          </Typography>
          <StatusIcon status={normalized.status} isMine={normalized.isMine} metaSx={metaSx} />
        </Box>
      </Box>
    </Box>
  );
}
