import React, { useMemo } from 'react';
import { Box, Typography } from '@mui/material';
import { Input, SearchableSelect } from '../../../../components/ui';
import { getFormControlSx } from '../../../../components/ui/Form/controls/formControlStyles';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';

function ParamValueField({ copy, field, onParamChange }) {
  const { semantic, typography } = useFeatureTheme();
  const showError = !field.isValid;
  const showMappedHint =
    !showError && !field.isMissingFromRecord && Boolean(field.mappedValue?.trim());

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.375, minWidth: 0, width: '100%' }}>
      <Input
        placeholder={copy.direct.paramValuePlaceholder}
        value={field.value}
        onChange={(event) => onParamChange?.(field.paramName, event.target.value)}
        error={showError}
        errorMessage={showError ? copy.direct.paramRequired : ''}
        size="sm"
        required
        aria-label={copy.direct.paramValue}
        sx={{ width: '100%' }}
      />
      {showMappedHint ? (
        <Typography
          sx={{ fontSize: typography.fontSizeXs, color: semantic.states.success, lineHeight: 1.3 }}
        >
          {copy.direct.fromRecordHint}
        </Typography>
      ) : null}
    </Box>
  );
}

export default function LeadSendTemplateMappingPanel({
  copy,
  styles,
  editableFields = [],
  columnOptions = [],
  onParamChange,
  onColumnSelect,
  stackFields = false,
}) {
  const themeTokens = useFeatureTheme();
  const { semantic, typography, controlHeights } = themeTokens;
  const hasColumnOptions = columnOptions.length > 0;
  const cellSx = styles?.leadSendTemplateParamFieldCell;
  const labelSx = styles?.leadSendTemplateParamFieldLabel;

  const selectSx = useMemo(
    () =>
      getFormControlSx(themeTokens, {
        '& .MuiOutlinedInput-root': {
          minHeight: controlHeights.sm,
        },
        '& .MuiFormHelperText-root': {
          display: 'none',
        },
      }),
    [controlHeights.sm, themeTokens]
  );

  const columnSelectOptions = useMemo(
    () => [
      { value: '', label: copy.direct.mapColumnNone },
      ...columnOptions.map((option) => ({
        value: option.value,
        label: option.label,
      })),
    ],
    [columnOptions, copy.direct.mapColumnNone]
  );

  if (!editableFields.length) {
    return (
      <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}>
        {copy.direct.noParamsRequired}
      </Typography>
    );
  }

  const renderMapColumnCell = (field) => (
    <Box sx={cellSx}>
      <Typography sx={labelSx}>{copy.direct.mapFromColumn}</Typography>
      <SearchableSelect
        placeholder={copy.direct.mapFromColumn}
        options={columnSelectOptions}
        value={
          columnSelectOptions.find((option) => option.value === (field.columnKey ?? ''))
          ?? columnSelectOptions[0]
        }
        onChange={(selected) => onColumnSelect?.(field.paramName, selected?.value ?? '')}
        labelKey="label"
        valueKey="value"
        clearable={false}
        size="small"
        sx={selectSx}
      />
      {field.isMissingFromRecord && !field.isValid ? (
        <Typography
          sx={{
            fontSize: typography.fontSizeXs,
            color: semantic.states.warning,
            lineHeight: 1.3,
          }}
        >
          {copy.direct.mapManuallyHint}
        </Typography>
      ) : null}
    </Box>
  );

  const renderValueCell = (field) => (
    <Box sx={cellSx}>
      <Typography sx={labelSx}>
        {copy.direct.paramValue}
        <Box component="span" sx={{ color: semantic.states.danger, ml: 0.25 }}>
          *
        </Box>
      </Typography>
      <ParamValueField copy={copy} field={field} onParamChange={onParamChange} />
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.875, minHeight: 0 }}>
      <Box>
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            fontWeight: typography.fontWeightSemibold,
            color: semantic.text.primary,
          }}
        >
          {copy.direct.fillMessageTitle}
        </Typography>
        <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary, mt: 0.25 }}>
          {copy.direct.fillMessageHint}
        </Typography>
      </Box>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.875, minHeight: 0 }}>
        {editableFields.map((field) => (
          <Box
            key={field.paramName}
            sx={styles?.leadSendTemplateParamRow}
          >
            <Typography
              sx={{
                fontSize: typography.fontSizeSm,
                fontWeight: typography.fontWeightSemibold,
                color: semantic.text.primary,
                mb: 0.5,
              }}
            >
              {copy.direct.paramLabel(field.variableIndex, field.label || field.paramName)}
            </Typography>

            {hasColumnOptions && stackFields ? (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75 }}>
                {renderMapColumnCell(field)}
                {renderValueCell(field)}
              </Box>
            ) : hasColumnOptions ? (
              <Box sx={styles?.leadSendTemplateParamFieldsGrid}>
                {renderMapColumnCell(field)}
                {renderValueCell(field)}
              </Box>
            ) : (
              <Box sx={styles?.leadSendTemplateParamFieldsGridSingle}>
                {renderValueCell(field)}
              </Box>
            )}
          </Box>
        ))}
      </Box>
    </Box>
  );
}
